contracts/ArcFlowPay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";
import "./lib/Security.sol";

/**
 * @title ArcFlowPay - Merchant payment system with receipts
 * @notice Merchants register, customers pay with any supported token, and every
 *         payment is recorded with a unique ID for verifiable history.
 *
 * @dev Merchant fee: the contract takes a small percentage (default 0.5%) from
 *      each payment to cover operations. The fee is transparent, deducted from
 *      the gross amount, and the merchant receives the net.
 *
 *      Multi-token support: customers may pay in any token; the merchant's
 *      on-chain ledger tracks totals per token. An off-chain integration or a
 *      future dashboard aggregates across tokens at current prices.
 */
contract ArcFlowPay is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Merchant {
        address wallet;
        string name;
        string category;
        bool active;
        uint64 registeredAt;
        // Total received in each token; viewed separately.
        mapping(address => uint256) totalReceivedByToken;
        uint256 paymentCount;
    }

    struct PaymentReceipt {
        uint256 id;
        address customer;
        address merchant;
        address token;
        uint256 grossAmount;
        uint256 fee;
        uint256 netAmount;
        uint64 timestamp;
        string memo; // optional customer note, e.g. "Invoice #1234"
    }

    /// @dev The next payment ID. Monotonic across all merchants/tokens.
    uint256 private _nextPaymentId;

    /// @dev `_payments[id]` is the full receipt.
    mapping(uint256 => PaymentReceipt) private _payments;

    /// @dev `_merchantPayments[merchant]` lists every payment ID received.
    mapping(address => uint256[]) private _merchantPayments;

    /// @dev `_customerPayments[customer]` lists every payment ID sent.
    mapping(address => uint256[]) private _customerPayments;

    mapping(address => Merchant) private _merchants;
    address[] private _merchantList;

    /// @dev Fee in basis points (0.01%). 50 = 0.5%. Capped at 5% (500 bps).
    uint256 public feeBps = 50;
    address public feeCollector;

    event MerchantRegistered(address indexed merchant, string name, string category);
    event MerchantDeactivated(address indexed merchant);
    event MerchantReactivated(address indexed merchant);
    event PaymentMade(
        uint256 indexed paymentId,
        address indexed customer,
        address indexed merchant,
        address token,
        uint256 grossAmount,
        uint256 fee,
        uint256 netAmount
    );
    event FeeUpdated(uint256 newFeeBps);
    event FeeCollectorUpdated(address indexed newCollector);

    constructor(address _feeCollector) Ownable2Step(msg.sender) {
        require(_feeCollector != address(0), "Zero fee collector");
        feeCollector = _feeCollector;
        _nextPaymentId = 1; // start IDs at 1 so 0 is reserved as "not found"
    }

    // ========================= Merchant registration =========================

    function registerMerchant(string calldata name, string calldata category) external whenNotPaused {
        require(bytes(name).length > 0, "Empty name");
        require(bytes(name).length <= 64, "Name too long");
        require(_merchants[msg.sender].wallet == address(0), "Already registered");

        Merchant storage m = _merchants[msg.sender];
        m.wallet = msg.sender;
        m.name = name;
        m.category = category;
        m.active = true;
        m.registeredAt = uint64(block.timestamp);
        m.paymentCount = 0;

        _merchantList.push(msg.sender);
        emit MerchantRegistered(msg.sender, name, category);
    }

    function deactivateMerchant(address merchant) external {
        require(msg.sender == owner || msg.sender == merchant, "Not authorized");
        Merchant storage m = _merchants[merchant];
        require(m.wallet != address(0), "Not registered");
        require(m.active, "Already inactive");

        m.active = false;
        emit MerchantDeactivated(merchant);
    }

    function reactivateMerchant() external {
        Merchant storage m = _merchants[msg.sender];
        require(m.wallet != address(0), "Not registered");
        require(!m.active, "Already active");

        m.active = true;
        emit MerchantReactivated(msg.sender);
    }

    // ========================= Payment =========================

    /**
     * @notice Pay a merchant in any token.
     * @param memo Optional short note attached to the receipt for bookkeeping.
     *
     * @dev Balance-diff pattern: measure the contract's token balance before and
     *      after the transfer to determine what actually arrived. This makes the
     *      contract safe for fee-on-transfer tokens, which deduct a cut in the
     *      `transferFrom` itself so `amount` would overstate what was received.
     */
    function pay(
        address merchant,
        address token,
        uint256 grossAmount,
        string calldata memo
    ) external whenNotPaused nonReentrant returns (uint256 paymentId) {
        require(grossAmount > 0, "Zero amount");
        require(token != address(0), "Zero token");
        require(bytes(memo).length <= 128, "Memo too long");

        Merchant storage m = _merchants[merchant];
        require(m.wallet != address(0), "Merchant not registered");
        require(m.active, "Merchant not active");

        IERC20 tokenContract = IERC20(token);
        uint256 before = tokenContract.balanceOf(address(this));
        tokenContract.safeTransferFrom(msg.sender, address(this), grossAmount);
        uint256 received = tokenContract.balanceOf(address(this)) - before;
        require(received > 0, "No tokens received");

        // Fee and net computed from what actually arrived, not from `grossAmount`.
        uint256 fee = (received * feeBps) / 10000;
        uint256 netAmount = received - fee;
        require(netAmount > 0, "Net amount zero");

        paymentId = _nextPaymentId++;

        _payments[paymentId] = PaymentReceipt({
            id: paymentId,
            customer: msg.sender,
            merchant: merchant,
            token: token,
            grossAmount: received,
            fee: fee,
            netAmount: netAmount,
            timestamp: uint64(block.timestamp),
            memo: memo
        });

        _merchantPayments[merchant].push(paymentId);
        _customerPayments[msg.sender].push(paymentId);

        m.totalReceivedByToken[token] += netAmount;
        m.paymentCount++;

        // Transfer net to merchant, fee to collector
        tokenContract.safeTransfer(merchant, netAmount);
        if (fee > 0) {
            tokenContract.safeTransfer(feeCollector, fee);
        }

        emit PaymentMade(paymentId, msg.sender, merchant, token, received, fee, netAmount);
    }

    // ========================= Views =========================

    function getMerchant(address wallet)
        external
        view
        returns (
            string memory name,
            string memory category,
            bool active,
            uint64 registeredAt,
            uint256 paymentCount
        )
    {
        Merchant storage m = _merchants[wallet];
        return (m.name, m.category, m.active, m.registeredAt, m.paymentCount);
    }

    /**
     * @notice How much a merchant has received in a specific token.
     * @dev To get total USD value, sum this across tokens using off-chain prices.
     */
    function getMerchantTotalByToken(address merchant, address token) external view returns (uint256) {
        return _merchants[merchant].totalReceivedByToken[token];
    }

    function getMerchantCount() external view returns (uint256) {
        return _merchantList.length;
    }

    function getMerchantList() external view returns (address[] memory) {
        return _merchantList;
    }

    function isRegistered(address wallet) external view returns (bool) {
        return _merchants[wallet].wallet != address(0);
    }

    function getPayment(uint256 paymentId)
        external
        view
        returns (
            address customer,
            address merchant,
            address token,
            uint256 grossAmount,
            uint256 fee,
            uint256 netAmount,
            uint64 timestamp,
            string memory memo
        )
    {
        PaymentReceipt storage r = _payments[paymentId];
        require(r.id == paymentId, "Payment not found");
        return (
            r.customer,
            r.merchant,
            r.token,
            r.grossAmount,
            r.fee,
            r.netAmount,
            r.timestamp,
            r.memo
        );
    }

    /**
     * @notice All payment IDs where `merchant` was the recipient.
     * @dev Unbounded in theory, but a realistic merchant receiving thousands of
     *      payments per day would accumulate ~1M entries per three years. The
     *      contract's own storage can handle it; if the array outgrows calldata
     *      limits, the frontend paginates by reading slices.
     */
    function getMerchantPayments(address merchant) external view returns (uint256[] memory) {
        return _merchantPayments[merchant];
    }

    function getCustomerPayments(address customer) external view returns (uint256[] memory) {
        return _customerPayments[customer];
    }

    function getNextPaymentId() external view returns (uint256) {
        return _nextPaymentId;
    }

    // ========================= Admin =========================

    function setFee(uint256 _feeBps) external onlyOwner {
        require(_feeBps <= 500, "Fee too high");
        feeBps = _feeBps;
        emit FeeUpdated(_feeBps);
    }

    function setFeeCollector(address _collector) external onlyOwner {
        require(_collector != address(0), "Zero fee collector");
        feeCollector = _collector;
        emit FeeCollectorUpdated(_collector);
    }

    function setPaused(bool value) external onlyOwner {
        _setPaused(value);
    }
}

contracts/ArcFlowRecurring.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";
import "./lib/Security.sol";

/**
 * @title ArcFlowRecurring - Subscription payments with keeper rewards
 * @notice Schedule recurring token payments; anyone can execute and earn a bounty.
 *
 * @dev Keeper economics: automation is not free. Gelato, Chainlink, or any other
 *      keeper network charges a gas fee plus a service fee for each execution.
 *      Without an on-chain incentive, no keeper would pick up this contract's
 *      recurring payments at all — running transactions for strangers at a loss
 *      is not a business model.
 *
 *      This contract makes execution profitable: a small percentage (default 1%)
 *      of each payment goes to whoever calls `executePayment`. The economics:
 *
 *      - Gas cost on Ethereum mainnet ~$2–5 per tx (depends on congestion)
 *      - A $100 monthly subscription with 1% keeper reward = $1 bounty
 *      - Not enough to cover mainnet gas, but viable on L2s
 *
 *      On Arbitrum or Optimism (gas ~$0.10), a 1% reward on $100 = $1 profit.
 *      On Polygon PoS (gas ~$0.01), profitable at even lower amounts.
 *
 *      A professional keeper runs a bot that scans for due payments, executes
 *      them, and collects the reward. The payer pre-approves enough allowance to
 *      cover the gross (payment + reward), so the keeper has no balance risk.
 *
 *      Alternative without a keeper reward: require the payer or payee to call
 *      `executePayment` themselves. That is not automatic; it is just a scheduled
 *      transfer they must remember to trigger. The product brief called for real
 *      automation, so this implements it honestly: permissionless execution with
 *      an economic incentive.
 *
 *      Keeper reward is configurable per payment (not global), so high-value
 *      subscriptions can set a larger percentage to compete for faster execution.
 *      The max is capped at 5% (500 bps) so a malicious payer cannot create a
 *      decoy payment that drains an keeper bot's ETH without paying out.
 */
contract ArcFlowRecurring is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum Frequency {
        Daily,
        Weekly,
        Monthly,
        Quarterly,
        Yearly
    }

    /**
     * @dev `payer`, `active`, `frequency`, `maxExecutions`, and `executions` are
     *      grouped for tight packing. `nextPayment` is hot and left in its own slot.
     */
    struct RecurringPayment {
        address payer;
        bool active;
        Frequency frequency;
        uint32 maxExecutions; // 0 = unlimited
        uint32 executions;
        address payee;
        address token;
        uint256 baseAmount; // net payment to payee
        uint256 keeperRewardBps; // basis points (0.01%); max 500
        uint256 startTime;
        uint256 nextPayment;
        uint256 totalPaid;
        string name;
    }

    uint256 private _nextPaymentId;
    mapping(uint256 => RecurringPayment) private _payments;
    mapping(address => uint256[]) private _payerPayments;
    mapping(address => uint256[]) private _payeePayments;

    /// @dev Max keeper reward: 5%. Higher is considered a scam bounty.
    uint256 public constant MAX_KEEPER_REWARD_BPS = 500;

    event RecurringCreated(
        uint256 indexed paymentId,
        address indexed payer,
        address indexed payee,
        address token,
        uint256 baseAmount,
        Frequency frequency,
        uint256 keeperRewardBps
    );
    event RecurringExecuted(
        uint256 indexed paymentId,
        address indexed executor,
        uint256 baseAmount,
        uint256 keeperReward
    );
    event RecurringCancelled(uint256 indexed paymentId);

    constructor() Ownable2Step(msg.sender) {
        _nextPaymentId = 1;
    }

    // ========================= Create =========================

    /**
     * @param keeperRewardBps Basis points paid to the executor. 100 = 1%.
     *        Higher values attract faster execution but cost the payer more.
     *        Capped at 5% to prevent abuse.
     */
    function createRecurring(
        address payee,
        address token,
        uint256 baseAmount,
        Frequency frequency,
        uint32 maxExecutions,
        uint256 keeperRewardBps,
        string calldata name
    ) external whenNotPaused returns (uint256 paymentId) {
        require(payee != address(0), "Zero payee");
        require(token != address(0), "Zero token");
        require(baseAmount > 0, "Zero amount");
        require(payee != msg.sender, "Self payment");
        require(bytes(name).length > 0, "Empty name");
        require(bytes(name).length <= 64, "Name too long");
        require(keeperRewardBps <= MAX_KEEPER_REWARD_BPS, "Keeper reward too high");

        paymentId = _nextPaymentId++;
        uint256 interval = _getInterval(frequency);

        _payments[paymentId] = RecurringPayment({
            payer: msg.sender,
            active: true,
            frequency: frequency,
            maxExecutions: maxExecutions,
            executions: 0,
            payee: payee,
            token: token,
            baseAmount: baseAmount,
            keeperRewardBps: keeperRewardBps,
            startTime: block.timestamp,
            nextPayment: block.timestamp + interval,
            totalPaid: 0,
            name: name
        });

        _payerPayments[msg.sender].push(paymentId);
        _payeePayments[payee].push(paymentId);

        emit RecurringCreated(
            paymentId,
            msg.sender,
            payee,
            token,
            baseAmount,
            frequency,
            keeperRewardBps
        );
    }

    // ========================= Execute =========================

    /**
     * @notice Execute a due payment; earn the keeper reward.
     * @dev Anyone may call. Execution is permissionless: the contract does not
     *      whitelist keepers, because that would centralize automation and make
     *      it easy for the owner to censor payments.
     *
     *      The schedule advances from the *due date*, not from now. A late keeper
     *      does not silently reduce the payer's annual payment count by delaying
     *      every subsequent interval. If multiple intervals elapsed, the schedule
     *      fast-forwards to the next future slot rather than allowing unbounded
     *      catch-up that would drain the payer's allowance in one transaction.
     */
    function executePayment(uint256 paymentId) external nonReentrant {
        RecurringPayment storage p = _payments[paymentId];
        require(p.payer != address(0), "Payment not found");
        require(p.active, "Not active");
        require(block.timestamp >= p.nextPayment, "Not due yet");
        require(p.maxExecutions == 0 || p.executions < p.maxExecutions, "Max reached");

        uint256 keeperReward = (p.baseAmount * p.keeperRewardBps) / 10000;
        uint256 grossAmount = p.baseAmount + keeperReward;

        IERC20 token = IERC20(p.token);
        uint256 before = token.balanceOf(address(this));
        token.safeTransferFrom(p.payer, address(this), grossAmount);
        uint256 received = token.balanceOf(address(this)) - before;
        require(received >= p.baseAmount, "Insufficient transfer");

        // Recompute splits from what actually arrived, in case token has transfer fees.
        uint256 actualReward = (received * p.keeperRewardBps) / (10000 + p.keeperRewardBps);
        uint256 actualBase = received - actualReward;

        uint256 interval = _getInterval(p.frequency);
        uint256 next = p.nextPayment + interval;
        if (next <= block.timestamp) {
            uint256 missed = (block.timestamp - p.nextPayment) / interval;
            next = p.nextPayment + (missed + 1) * interval;
        }

        // Effects before final transfers
        p.executions++;
        p.totalPaid += actualBase;
        p.nextPayment = next;

        if (p.maxExecutions > 0 && p.executions >= p.maxExecutions) {
            p.active = false;
        }

        // Transfer base to payee, reward to executor (msg.sender = keeper bot or manual caller)
        token.safeTransfer(p.payee, actualBase);
        if (actualReward > 0) {
            token.safeTransfer(msg.sender, actualReward);
        }

        emit RecurringExecuted(paymentId, msg.sender, actualBase, actualReward);
    }

    // ========================= Cancel =========================

    function cancelRecurring(uint256 paymentId) external {
        RecurringPayment storage p = _payments[paymentId];
        require(p.payer != address(0), "Payment not found");
        require(msg.sender == p.payer || msg.sender == owner, "Not authorized");
        require(p.active, "Already cancelled");

        p.active = false;
        emit RecurringCancelled(paymentId);
    }

    // ========================= Views =========================

    function getPayment(uint256 paymentId)
        external
        view
        returns (
            address payer,
            address payee,
            address token,
            uint256 baseAmount,
            uint256 keeperRewardBps,
            Frequency frequency,
            uint256 nextPayment,
            uint256 totalPaid,
            uint32 executions,
            uint32 maxExecutions,
            bool active,
            string memory name
        )
    {
        RecurringPayment storage p = _payments[paymentId];
        require(p.payer != address(0), "Payment not found");
        return (
            p.payer,
            p.payee,
            p.token,
            p.baseAmount,
            p.keeperRewardBps,
            p.frequency,
            p.nextPayment,
            p.totalPaid,
            p.executions,
            p.maxExecutions,
            p.active,
            p.name
        );
    }

    function getPayerPayments(address user) external view returns (uint256[] memory) {
        return _payerPayments[user];
    }

    function getPayeePayments(address user) external view returns (uint256[] memory) {
        return _payeePayments[user];
    }

    function getNextPaymentId() external view returns (uint256) {
        return _nextPaymentId;
    }

    /**
     * @notice Whether a payment is due and executable right now.
     * @dev Keeper bots query this across many payment IDs to find work.
     */
    function isDue(uint256 paymentId) external view returns (bool) {
        RecurringPayment storage p = _payments[paymentId];
        return
            p.payer != address(0) &&
            p.active &&
            block.timestamp >= p.nextPayment &&
            (p.maxExecutions == 0 || p.executions < p.maxExecutions);
    }

    /**
     * @notice Gross amount the payer must approve: base + keeper reward.
     * @dev A UI uses this to prompt the correct `approve` call before creating.
     */
    function getGrossAmount(uint256 paymentId) external view returns (uint256) {
        RecurringPayment storage p = _payments[paymentId];
        require(p.payer != address(0), "Payment not found");
        return p.baseAmount + (p.baseAmount * p.keeperRewardBps) / 10000;
    }

    // ========================= Internal =========================

    function _getInterval(Frequency f) internal pure returns (uint256) {
        if (f == Frequency.Daily) return 1 days;
        if (f == Frequency.Weekly) return 7 days;
        if (f == Frequency.Monthly) return 30 days;
        if (f == Frequency.Quarterly) return 90 days;
        return 365 days; // Yearly
    }

    // ========================= Admin =========================

    function setPaused(bool value) external onlyOwner {
        _setPaused(value);
    }
}

contracts/ArcFlowSplit.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";
import "./lib/Security.sol";

/**
 * @title ArcFlowSplit - Group expense splitting with escrow
 * @notice Create a split, let members join, collect each share, then release
 *         the full amount to the recipient in one settlement.
 *
 * @dev Escrow rather than pass-through, and the reason matters:
 *
 *      A pass-through design (forward each share straight to the recipient)
 *      cannot express "settle" as a real operation — the group is just a
 *      counter, and a recipient receives N dribbles with no guarantee the group
 *      ever completes. Escrow makes the group atomic from the recipient's view:
 *      they receive the whole bill once, or the split is cancelled and every
 *      member is refunded exactly what they put in.
 *
 *      The tradeoff is that this contract custodies funds between payment and
 *      settlement, so the refund path is a first-class feature rather than an
 *      afterthought, and withdrawals stay open even when the contract is paused.
 *
 *      Per-group token: the token is fixed at creation and every share is
 *      denominated in it. Mixing tokens inside one group would make `collected`
 *      meaningless.
 */
contract ArcFlowSplit is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @dev Open accepts joins; Locked is fully subscribed; Settled paid out.
    enum SplitStatus {
        Open,
        Locked,
        Settled,
        Cancelled
    }

    /**
     * @dev Small fields grouped so the hot ones share slots. `memberCount` and
     *      `paidCount` are uint32 (50-member cap makes overflow impossible) and
     *      `createdAt` is uint64 (safe past year 500 billion).
     */
    struct SplitGroup {
        address creator;
        uint32 memberCount;
        uint32 paidCount;
        SplitStatus status;
        bool openJoin;
        address recipient;
        uint64 createdAt;
        address token;
        uint256 committed; // sum of every member's share
        uint256 collected; // sum actually escrowed
        string name;
    }

    struct Member {
        address wallet;
        uint256 share;
        uint256 paidAmount; // escrowed by this member; refundable on cancel
        bool paid;
        uint64 paidAt;
    }

    /// @dev Bounded so `getGroupMembers` and the create loop stay callable.
    uint256 public constant MAX_MEMBERS = 50;

    SplitGroup[] private _groups;
    mapping(uint256 => Member[]) private _members;
    mapping(uint256 => mapping(address => bool)) public isMember;
    mapping(uint256 => mapping(address => uint256)) private _memberIndex;
    mapping(address => uint256[]) private _userGroups;

    event GroupCreated(
        uint256 indexed groupId,
        address indexed creator,
        address indexed token,
        address recipient,
        string name,
        bool openJoin
    );
    event MemberAdded(uint256 indexed groupId, address indexed member, uint256 share);
    event MemberJoined(uint256 indexed groupId, address indexed member, uint256 share);
    event SharePaid(uint256 indexed groupId, address indexed member, uint256 amount);
    event GroupLocked(uint256 indexed groupId, uint256 committed);
    event GroupSettled(uint256 indexed groupId, address indexed recipient, uint256 amount);
    event GroupCancelled(uint256 indexed groupId);
    event Refunded(uint256 indexed groupId, address indexed member, uint256 amount);

    constructor() Ownable2Step(msg.sender) {}

    // ========================= Create =========================

    /**
     * @notice Create a split group.
     * @param members Optional preset members. May be empty when `openJoin` is
     *                true, which is how "share a link, people join themselves"
     *                works without the creator knowing addresses up front.
     * @param openJoin Whether others may join after creation.
     *
     * @dev The recipient is fixed here and never re-read from caller input, so
     *      no member can redirect the payout at settlement time.
     */
    function createSplit(
        string calldata name,
        address token,
        address recipient,
        address[] calldata members,
        uint256[] calldata shares,
        bool openJoin
    ) external whenNotPaused returns (uint256 groupId) {
        require(bytes(name).length > 0, "Empty name");
        require(bytes(name).length <= 64, "Name too long");
        require(token != address(0), "Zero token");
        require(recipient != address(0), "Zero recipient");
        require(members.length == shares.length, "Length mismatch");
        require(members.length <= MAX_MEMBERS, "Too many members");
        // A closed group with no members could never be settled or cancelled
        // into a meaningful state, so reject it at creation.
        require(openJoin || members.length > 0, "Closed group needs members");

        groupId = _groups.length;

        _groups.push(
            SplitGroup({
                creator: msg.sender,
                memberCount: 0,
                paidCount: 0,
                status: SplitStatus.Open,
                openJoin: openJoin,
                recipient: recipient,
                createdAt: uint64(block.timestamp),
                token: token,
                committed: 0,
                collected: 0,
                name: name
            })
        );

        emit GroupCreated(groupId, msg.sender, token, recipient, name, openJoin);

        uint256 committed;
        for (uint256 i = 0; i < members.length; i++) {
            address member = members[i];
            require(member != address(0), "Zero member");
            require(shares[i] > 0, "Zero share");
            require(!isMember[groupId][member], "Duplicate member");

            committed += shares[i];
            _addMember(groupId, member, shares[i]);
            emit MemberAdded(groupId, member, shares[i]);
        }

        SplitGroup storage g = _groups[groupId];
        g.committed = committed;
        g.memberCount = uint32(members.length);

        // A fully-specified closed group is immediately locked: nobody can join,
        // so its membership is already final.
        if (!openJoin) {
            g.status = SplitStatus.Locked;
            emit GroupLocked(groupId, committed);
        }
    }

    function _addMember(uint256 groupId, address member, uint256 share) private {
        _memberIndex[groupId][member] = _members[groupId].length;
        _members[groupId].push(
            Member({wallet: member, share: share, paidAmount: 0, paid: false, paidAt: 0})
        );
        isMember[groupId][member] = true;
        _userGroups[member].push(groupId);
    }

    // ========================= Join =========================

    /**
     * @notice Join an open split with a self-declared share.
     * @dev Only valid while the group is Open. Joining does not transfer funds;
     *      {payShare} does. Separating them means a member can commit to a share
     *      before having the balance, which is how real bill-splitting works.
     */
    function joinSplit(uint256 groupId, uint256 share) external whenNotPaused {
        SplitGroup storage g = _requireGroup(groupId);
        require(g.openJoin, "Not open to join");
        require(g.status == SplitStatus.Open, "Not accepting members");
        require(!isMember[groupId][msg.sender], "Already a member");
        require(share > 0, "Zero share");
        require(g.memberCount < MAX_MEMBERS, "Group full");

        g.committed += share;
        g.memberCount += 1;
        _addMember(groupId, msg.sender, share);

        emit MemberJoined(groupId, msg.sender, share);
    }

    /**
     * @notice Stop accepting new members.
     * @dev Locking is what makes `committed` final, which settlement depends on.
     *      Restricted to the creator: letting any member lock would let one
     *      person freeze others out of a group they were invited to.
     */
    function lockGroup(uint256 groupId) external {
        SplitGroup storage g = _requireGroup(groupId);
        require(msg.sender == g.creator, "Not creator");
        require(g.status == SplitStatus.Open, "Not open");
        require(g.memberCount > 0, "No members");

        g.status = SplitStatus.Locked;
        emit GroupLocked(groupId, g.committed);
    }

    // ========================= Pay =========================

    /**
     * @notice Escrow the caller's share.
     * @dev Balance is checked against the amount actually received rather than
     *      trusting the requested amount, so fee-on-transfer tokens cannot
     *      credit a member for more than the contract holds — which would leave
     *      settlement permanently short and the group stuck.
     */
    function payShare(uint256 groupId) external whenNotPaused nonReentrant {
        SplitGroup storage g = _requireGroup(groupId);
        require(
            g.status == SplitStatus.Open || g.status == SplitStatus.Locked,
            "Not payable"
        );
        require(isMember[groupId][msg.sender], "Not a member");

        Member storage m = _members[groupId][_memberIndex[groupId][msg.sender]];
        require(!m.paid, "Already paid");

        uint256 share = m.share;
        IERC20 token = IERC20(g.token);

        uint256 before = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), share);
        uint256 received = token.balanceOf(address(this)) - before;
        require(received > 0, "No tokens received");

        m.paid = true;
        m.paidAmount = received;
        m.paidAt = uint64(block.timestamp);
        g.paidCount += 1;
        g.collected += received;

        emit SharePaid(groupId, msg.sender, received);
    }

    // ========================= Settle =========================

    /**
     * @notice Release the escrowed total to the recipient.
     * @dev Requires every member to have paid. Callable by the creator or the
     *      recipient — both have a direct interest in completion, and requiring
     *      only the creator would strand funds if they went away.
     */
    function settle(uint256 groupId) external nonReentrant {
        SplitGroup storage g = _requireGroup(groupId);
        require(g.status == SplitStatus.Locked, "Not locked");
        require(g.paidCount == g.memberCount, "Not fully paid");
        require(msg.sender == g.creator || msg.sender == g.recipient, "Not authorized");

        uint256 amount = g.collected;
        require(amount > 0, "Nothing to settle");

        // Effects before the transfer, and `collected` zeroed so a reentrant
        // call finds nothing left to pay out.
        g.status = SplitStatus.Settled;
        g.collected = 0;

        IERC20(g.token).safeTransfer(g.recipient, amount);
        emit GroupSettled(groupId, g.recipient, amount);
    }

    // ========================= Cancel & refund =========================

    /**
     * @notice Cancel before settlement; members reclaim their escrow.
     * @dev Cancelling does not push refunds. Looping transfers over up to 50
     *      members can exceed the block gas limit, and one member on a token
     *      blocklist would revert the whole loop and trap everyone's funds.
     *      Each member pulls their own instead.
     */
    function cancelSplit(uint256 groupId) external {
        SplitGroup storage g = _requireGroup(groupId);
        require(msg.sender == g.creator || msg.sender == owner, "Not authorized");
        require(
            g.status == SplitStatus.Open || g.status == SplitStatus.Locked,
            "Not cancellable"
        );

        g.status = SplitStatus.Cancelled;
        emit GroupCancelled(groupId);
    }

    /**
     * @notice Withdraw your escrow from a cancelled group.
     * @dev Intentionally has no `whenNotPaused`: pausing must never trap funds
     *      that already belong to a user.
     */
    function withdrawRefund(uint256 groupId) external nonReentrant {
        SplitGroup storage g = _requireGroup(groupId);
        require(g.status == SplitStatus.Cancelled, "Not cancelled");
        require(isMember[groupId][msg.sender], "Not a member");

        Member storage m = _members[groupId][_memberIndex[groupId][msg.sender]];
        uint256 amount = m.paidAmount;
        require(amount > 0, "Nothing to refund");

        // Zeroed before the transfer so a reentrant call cannot double-refund.
        m.paidAmount = 0;
        m.paid = false;
        g.collected -= amount;

        IERC20(g.token).safeTransfer(msg.sender, amount);
        emit Refunded(groupId, msg.sender, amount);
    }

    // ========================= Views =========================

    function _requireGroup(uint256 groupId) private view returns (SplitGroup storage) {
        require(groupId < _groups.length, "Invalid group");
        return _groups[groupId];
    }

    function getGroup(uint256 groupId)
        external
        view
        returns (
            address creator,
            address recipient,
            address token,
            string memory name,
            uint256 committed,
            uint256 collected,
            uint32 memberCount,
            uint32 paidCount,
            SplitStatus status,
            bool openJoin,
            uint64 createdAt
        )
    {
        SplitGroup storage g = _requireGroup(groupId);
        return (
            g.creator,
            g.recipient,
            g.token,
            g.name,
            g.committed,
            g.collected,
            g.memberCount,
            g.paidCount,
            g.status,
            g.openJoin,
            g.createdAt
        );
    }

    function getGroupMembers(uint256 groupId)
        external
        view
        returns (
            address[] memory wallets,
            uint256[] memory shares,
            uint256[] memory paidAmounts,
            bool[] memory paid
        )
    {
        Member[] storage list = _members[groupId];
        uint256 len = list.length;
        wallets = new address[](len);
        shares = new uint256[](len);
        paidAmounts = new uint256[](len);
        paid = new bool[](len);

        for (uint256 i = 0; i < len; i++) {
            wallets[i] = list[i].wallet;
            shares[i] = list[i].share;
            paidAmounts[i] = list[i].paidAmount;
            paid[i] = list[i].paid;
        }
    }

    function getUserGroups(address user) external view returns (uint256[] memory) {
        return _userGroups[user];
    }

    /// @notice What `user` still owes for a group; 0 if paid or not a member.
    function getOutstandingShare(uint256 groupId, address user) external view returns (uint256) {
        if (groupId >= _groups.length || !isMember[groupId][user]) return 0;
        Member storage m = _members[groupId][_memberIndex[groupId][user]];
        return m.paid ? 0 : m.share;
    }

    /// @notice Refundable escrow for `user` after cancellation.
    function getRefundable(uint256 groupId, address user) external view returns (uint256) {
        if (groupId >= _groups.length || !isMember[groupId][user]) return 0;
        if (_groups[groupId].status != SplitStatus.Cancelled) return 0;
        return _members[groupId][_memberIndex[groupId][user]].paidAmount;
    }

    function getGroupCount() external view returns (uint256) {
        return _groups.length;
    }

    // ========================= Admin =========================

    function setPaused(bool value) external onlyOwner {
        _setPaused(value);
    }
}

